import 'dart:convert';
import 'dart:io';

import 'package:contracts/contracts.dart';
import 'package:quran_text/quran_text.dart';
import 'package:test/test.dart';

/// Generated by tools/content_build from the downloaded canon (P03).
const String fixturePath = '../testing/fixtures/content_p582_583.json';

List<Word> loadFixture() => switch (
        ContentJsonSource(File(fixturePath).readAsStringSync()).loadWords()) {
      Ok(:final value) => value,
      Error(:final error) => throw error,
    };

void main() {
  late List<Word> words;
  late InMemoryQuranText text;
  const builtIn = NormalizerId('builtin-10.1');

  setUpAll(() {
    words = loadFixture();
    text = InMemoryQuranText(
      words: words,
      normalizers: [Normalizer.builtIn],
      params: SearchParams.defaults,
    );
  });

  group('ContentJsonSource', () {
    test('loads all words of pages 582–583 in order', () {
      expect(words, hasLength(218));
      expect(words.first.key, const WordKey(78, 1, 1));
      expect(words.where((w) => w.key.surah == 78), hasLength(173));
      expect(words.first.page, 582);
    });

    test('rejects other formats and malformed rows', () {
      for (final bad in [
        '{"format": 2, "words": []}',
        '{"format": 1, "words": [{"surah": 78}]}',
        '{"format": 1}',
        'nope',
      ]) {
        expect(
          ContentJsonSource(bad).loadWords(),
          isA<Error<List<Word>>>(),
          reason: bad,
        );
      }
    });
  });

  group('canon', () {
    test('is not changed by building keys and the index', () {
      final fresh = loadFixture();
      expect(text.words, fresh);
      for (var i = 0; i < fresh.length; i++) {
        expect(text.words[i].text, fresh[i].text);
      }
    });

    test('keys differ from the canon text (they are not for display)', () {
      final changed = words.where(
        (w) => text.searchKey(w.key, builtIn).value != w.text,
      );
      // Every canonical word carries harakat, so every key differs.
      expect(changed, hasLength(words.length));
    });

    test('word keys are never empty', () {
      for (final w in words) {
        expect(text.searchKey(w.key, builtIn).isEmpty, isFalse);
      }
    });
  });

  group('word and range', () {
    test('word returns the canon at a key', () {
      final w = text.word(const WordKey(78, 2, 1));
      expect(w.key, const WordKey(78, 2, 1));
      expect(w.index, words[2].index);
    });

    test('range is inclusive and in reading order, across surahs', () {
      final r = text.range(const WordKey(78, 40, 1), const WordKey(79, 1, 2));
      expect(r.first.key, const WordKey(78, 40, 1));
      expect(r.last.key, const WordKey(79, 1, 2));
      for (var i = 1; i < r.length; i++) {
        expect(r[i].index, r[i - 1].index + 1);
      }
    });

    test('unknown keys and reversed ranges are errors', () {
      expect(() => text.word(const WordKey(2, 255, 1)), throwsArgumentError);
      expect(
        () => text.range(const WordKey(78, 2, 1), const WordKey(78, 1, 1)),
        throwsArgumentError,
      );
      expect(
        () => text.searchKey(words.first.key, const NormalizerId('x')),
        throwsArgumentError,
      );
    });
  });

  group('findSequence', () {
    List<SearchKey> keysOf(Iterable<Word> ws) => [
          for (final w in ws) text.searchKey(w.key, builtIn),
        ];

    test('finds an ayah by 3 words from its middle', () {
      // 78:38 is a long ayah; take its words 4..6.
      final ayah = words.where((w) => w.key.surah == 78 && w.key.ayah == 38);
      final middle = ayah.skip(3).take(3).toList();
      final matches = text.findSequence(keysOf(middle), normalizer: builtIn);
      expect(matches.first.start, const WordKey(78, 38, 4));
      expect(matches.first.matchedNgrams, 1);
    });

    test('every 3-word window of the fixture finds its own place', () {
      for (var i = 0; i + 3 <= words.length; i++) {
        final window = words.sublist(i, i + 3);
        final matches = text.findSequence(keysOf(window), normalizer: builtIn);
        final best = matches.first.matchedNgrams;
        final top = matches.where((m) => m.matchedNgrams == best);
        expect(
          top.map((m) => m.start),
          contains(words[i].key),
          reason: '${words[i].key}',
        );
      }
    });

    test('a longer query with one wrong word still finds the place', () {
      final query = keysOf(words.sublist(50, 56));
      query[5] = const SearchKey('zzz');
      final matches = text.findSequence(query, normalizer: builtIn);
      expect(matches.first.start, words[50].key);
      expect(matches.first.matchedNgrams, 3);
    });

    test('finds nothing for fewer than ngramSize words or unknown keys', () {
      expect(
        text.findSequence(keysOf(words.take(2)), normalizer: builtIn),
        isEmpty,
      );
      expect(
        text.findSequence(
          const [SearchKey('x'), SearchKey('y'), SearchKey('z')],
          normalizer: builtIn,
        ),
        isEmpty,
      );
    });

    test('respects maxResults', () {
      final query = keysOf(words.sublist(10, 13));
      expect(
        text.findSequence(query, normalizer: builtIn, maxResults: 0),
        isEmpty,
      );
    });
  });

  group('NgramIndex', () {
    test('indexes every window of ngramSize keys', () {
      final keys = [for (final c in 'abcab'.split('')) SearchKey(c)];
      final index = NgramIndex(keys, ngramSize: 2);
      expect(index.size, 3); // ab, bc, ca
      final hits = index.find(
        [
          const SearchKey('a'),
          const SearchKey('b'),
        ],
        maxResults: 10,
      );
      expect(hits.map((h) => h.start), [0, 3]);
    });
  });

  test('content JSON field names stay in sync with content_build', () {
    final json = jsonDecode(File(fixturePath).readAsStringSync())
        as Map<String, Object?>;
    expect(json['format'], ContentJsonSource.supportedFormat);
  });
}
